    "lawName": "STJ - Súmula 523",
    "article": "Súmula 523",
    "title": "DIREITO TRIBUTÁRIO: REPETIÇÃO DE INDÉBITO",
    "content": "A taxa de juros de mora incidente na repetição de indébito de tributos estaduais deve corresponder à utilizada para cobrança do tributo pago em atraso, sendo legítima a incidência da taxa Selic, em ambas as hipóteses, quando prevista na legislação local, vedada sua cumulação com quaisquer outros índices.",
