    "lawName": "STJ - Súmula 524",
    "article": "Súmula 524",
    "title": "DIREITO TRIBUTÁRIO: ISS",
    "content": "No tocante à base de cálculo, o ISSQN incide apenas sobre a taxa de agenciamento quando o serviço prestado por sociedade empresária de trabalho temporário for de intermediação, devendo, entretanto, englobar também os valores dos salários e encargos sociais dos trabalhadores por ela contratados nas hipóteses de fornecimento de mão de obra.",
