    "lawName": "STJ - Súmula 550",
    "article": "Súmula 550",
    "title": "DIREITO DO CONSUMIDOR: SISTEMA CREDIT SCORING",
    "content": "A utilização de escore de crédito, método estatístico de avaliação de risco que não constitui banco de dados, dispensa o consentimento do consumidor, que terá o direito de solicitar esclarecimentos sobre as informações pessoais valoradas e as fontes dos dados considerados no respectivo cálculo.",
