    "lawName": "STJ - Súmula 551",
    "article": "Súmula 551",
    "title": "DIREITO DO CONSUMIDOR: TELEFONIA",
    "content": "Nas demandas por complementação de ações de empresas de telefonia, admite-se a condenação ao pagamento de dividendos e juros sobre capital próprio independentemente de pedido expresso. No entanto, somente quando previstos no título executivo, poderão ser objeto de cumprimento de sentença.",
