    "article": "Súmula 554",
    "title": "DIREITO TRIBUTÁRIO: RESPONSABILIDADE TRIBUTÁRIA",
    "content": "Na hipótese de sucessão empresarial, a responsabilidade da sucessora abrange não apenas os tributos devidos pela sucedida, mas também as multas moratórias ou punitivas referentes a fatos geradores ocorridos até a data da sucessão.",
