    "article": "Súmula 555",
    "title": "DIREITO TRIBUTÁRIO: CRÉDITO TRIBUTÁRIO",
    "content": "Quando não houver declaração do débito, o prazo decadencial quinquenal para o Fisco constituir o crédito tributário conta-se exclusivamente na forma do art. 173, I, do CTN, nos casos em que a legislação atribui ao sujeito passivo o dever de antecipar o pagamento sem prévio exame da autoridade administrativa.",
