    "lawName": "STJ - Súmula 556",
    "article": "Súmula 556",
    "title": "DIREITO TRIBUTÁRIO: IMPOSTO DE RENDA",
    "content": "É indevida a incidência de imposto de renda sobre o valor da complementação de aposentadoria pago por entidade de previdência privada e em relação ao resgate de contribuições recolhidas para referidas entidades patrocinadoras no período de 1º/1/1989 a 31/12/1995, em razão da isenção concedida pelo art. 6º, VII, b, da Lei n. 7.713/1988, na redação anterior à que lhe foi dada pela Lei n. 9.250/1995.",
