    "lawName": "STJ - Súmula 564",
    "article": "Súmula 564",
    "title": "DIREITO EMPRESARIAL: ARRENDAMENTO MERCANTIL",
    "content": "No caso de reintegração de posse em arrendamento mercantil financeiro, quando a soma da importância antecipada a título de valor residual garantido (VRG) com o valor da venda do bem ultrapassar o total do VRG previsto contratualmente, o arrendatário terá direito de receber a respectiva diferença, cabendo, porém, se estipulado no contrato, o prévio desconto de outras despesas ou encargos pactuados.",
