    "article": "Súmula 574",
    "title": "DIREITO PENAL: VIOLAÇÃO A DIREITO AUTORAL",
    "content": "Para a configuração do delito de violação de direito autoral e a comprovação de sua materialidade, é suficiente a perícia realizada por amostragem do produto apreendido, nos aspectos externos do material, e é desnecessária a identificação dos titulares dos direitos autorais violados ou daqueles que os representem.",
