    "lawName": "STJ - Súmula 575",
    "article": "Súmula 575",
    "title": "DIREITO PENAL: CRIMES DE TRÂNSITO",
    "content": "Constitui crime a conduta de permitir, confiar ou entregar a direção de veículo automotor a pessoa que não seja habilitada, ou que se encontre em qualquer das situações previstas no art. 310 do CTB, independentemente da ocorrência de lesão ou de perigo de dano concreto na condução do veículo.",
