    "article": "Súmula 581",
    "title": "DIREITO EMPRESARIAL: RECUPERAÇÃO JUDICIAL",
    "content": "A recuperação judicial do devedor principal não impede o prosseguimento das ações e execuções ajuizadas contra terceiros devedores solidários ou coobrigados em geral, por garantia cambial, real ou fidejussória.",
