    "lawName": "STJ - Súmula 582",
    "article": "Súmula 582",
    "title": "DIREITO PENAL: ROUBO",
    "content": "Consuma-se o crime de roubo com a inversão da posse do bem mediante emprego de violência ou grave ameaça, ainda que por breve tempo e em seguida à perseguição imediata ao agente e recuperação da coisa roubada, sendo prescindível a posse mansa e pacífica ou desvigiada.",
