    "lawName": "STJ - Súmula 583",
    "article": "Súmula 583",
    "title": "DIREITO TRIBUTÁRIO: EXECUÇÃO FISCAL",
    "content": "O arquivamento provisório previsto no art. 20 da Lei n. 10.522/2002, dirigido aos débitos inscritos como dívida ativa da União pela Procuradoria-Geral da Fazenda Nacional ou por ela cobrados, não se aplica às execuções fiscais movidas pelos conselhos de fiscalização profissional ou pelas autarquias federais.",
