    "article": "Súmula 584",
    "title": "DIREITO TRIBUTÁRIO: CONTRIBUIÇÃO PARA FINANCIAMENTO DA SEGURIDADE SOCIAL",
    "content": "As sociedades corretoras de seguros, que não se confundem com as sociedades de valores mobiliários ou com os agentes autônomos de seguro privado, estão fora do rol de entidades constantes do art. 22, § 1º, da Lei n. 8.212/1991, não se sujeitando à majoração da alíquota da Cofins prevista no art. 18 da Lei n. 10.684/2003.",
