    "article": "Súmula 585",
    "title": "DIREITO TRIBUTÁRIO: IPVA",
    "content": "A responsabilidade solidária do ex-proprietário, prevista no art. 134 do Código de Trânsito Brasileiro - CTB, não abrange o IPVA incidente sobre o veículo automotor, no que se refere ao período posterior à sua alienação.",
