    "title": "DIREITO PENAL: LEI MARIA DA PENHA",
    "content": "A prática de crime ou contravenção penal contra a mulher com violência ou grave ameaça no ambiente doméstico impossibilita a substituição da pena privativa de liberdade por restritiva de direitos.",
