    "lawName": "STJ - Súmula 593",
    "article": "Súmula 593",
    "title": "DIREITO PENAL: ESTUPRO",
    "content": "O crime de estupro de vulnerável se configura com a conjunção carnal ou prática de ato libidinoso com menor de 14 anos, sendo irrelevante eventual consentimento da vítima para a prática do ato, sua experiência sexual anterior ou existência de relacionamento amoroso com o agente.",
