    "lawName": "STJ - Súmula 594",
    "article": "Súmula 594",
    "title": "DIREITO DA CRIANÇA E DO ADOLESCENTE: AÇÃO DE ALIMENTOS",
    "content": "O Ministério Público tem legitimidade ativa para ajuizar ação de alimentos em proveito de criança ou adolescente independentemente do exercício do poder familiar dos pais, ou do fato de o menor se encontrar nas situações de risco descritas no art. 98 do Estatuto da Criança e do Adolescente, ou de quaisquer outros questionamentos acerca da existência ou eficiência da Defensoria Pública na comarca.",
