    "article": "Súmula 596",
    "title": "DIREITO CIVIL: ALIMENTOS",
    "content": "A obrigação alimentar dos avós tem natureza complementar e subsidiária, somente se configurando no caso de impossibilidade total ou parcial de seu cumprimento pelos pais.",
