    "article": "Súmula 597",
    "title": "DIREITO DO CONSUMIDOR: PLANO DE SAÚDE",
    "content": "A cláusula contratual de plano de saúde que prevê carência para utilização dos serviços de assistência médica nas situações de emergência ou de urgência é considerada abusiva se ultrapassado o prazo máximo de 24 horas contado da data da contratação.",
