    "article": "Súmula 598",
    "title": "DIREITO TRIBUTÁRIO: IMPOSTO DE RENDA",
    "content": "É desnecessária a apresentação de laudo médico oficial para o reconhecimento judicial da isenção do imposto de renda, desde que o magistrado entenda suficientemente demonstrada a doença grave por outros meios de prova.",
