    "article": "Súmula 630",
    "title": "DIREITO PENAL: APLICAÇÃO DA PENA",
    "content": "A incidência da atenuante da confissão espontânea no crime de tráfico ilícito de entorpecentes quando o acusado admitir a posse ou a propriedade para uso próprio, negando a prática do tráfico de drogas, deve ocorrer em proporção inferior à que seria devida no caso de confissão plena.",
