    "lawName": "STJ - Súmula 665",
    "article": "Súmula 665",
    "title": "DIREITO ADMINISTRATIVO: PROCESSO ADMINISTRATIVO DISCIPLINAR",
    "content": "O controle jurisdicional do processo administrativo disciplinar restringe-se ao exame da regularidade do procedimento e da legalidade do ato, à luz dos princípios do contraditório, da ampla defesa e do devido processo legal, não sendo possível incursão no mérito administrativo, ressalvadas as hipóteses de flagrante ilegalidade, teratologia ou manifesta desproporcionalidade da sanção aplicada.",
