    "article": "Súmula 666",
    "title": "DIREITO TRIBUTÁRIO: REPETIÇÃO DE INDÉBITO",
    "content": "A legitimidade passiva, em demandas que visam à restituição de contribuições de terceiros, está vinculada à capacidade tributária ativa; assim, nas hipóteses em que as entidades terceiras são meras destinatárias das contribuições, não possuem elas legitimidade ad causam para figurar no polo passivo, juntamente com a União.",
